BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats6-q01', '因果推論',
   '「猫を飼っている家庭ほど、家計の貯金が多い」というデータが見つかった。このデータだけから言えることとして正しいのはどれ？',
   NULL::text,
   '["猫を飼うことと貯金の多さには相関があるが、猫が原因で貯金が増えるとは言えない", "猫を飼うようになったこと自体が原因で、余計な出費が減って貯金が増えることが証明された", "貯金が多い家庭であることが原因で、あとから猫を飼うようになることが証明された", "猫を飼うことと貯金の額のあいだには、統計的にまったく関係がないことがわかった"]',
   0, '[0]', 'single',
   '{"asked": "「2つのことが一緒に動いて見える」ことと「片方がもう片方の原因である」ことの違い。", "point": "一緒に動いて見える（相関）だけでは、原因と結果の向き（因果）までは分からない。", "kid": "相関は「AとBが一緒に増えたり減ったりする」という事実だけを言っている。因果は「Aが原因でBが起きた」というもっと強い主張。事実だけを見て、いきなり原因を決めつけてはいけない。", "eg": "傘を差している人が増える日は雨がよく降っている。でも「傘が雨を降らせている」わけではない。傘と雨は一緒に動いているだけで、原因は別（空の様子）にある。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">「AとBが一緒に動く」だけ見えたとき、原因はこの3通りありうる</text><text x=\"58\" y=\"42\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">A</text><line x1=\"70\" y1=\"38\" x2=\"104\" y2=\"38\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"104,38 98.5,40.3 98.5,35.7\" fill=\"#60a5fa\"/><text x=\"116\" y=\"42\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">B</text><text x=\"88\" y=\"58\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">Aが原因でBが起きた</text><text x=\"58\" y=\"90\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">A</text><line x1=\"104\" y1=\"86\" x2=\"70\" y2=\"86\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"70,86 75.5,83.7 75.5,88.3\" fill=\"#60a5fa\"/><text x=\"116\" y=\"90\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">B</text><text x=\"88\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">逆にBが原因でAが起きた</text><text x=\"250\" y=\"34\" fill=\"#c9a04a\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">C</text><line x1=\"244\" y1=\"42\" x2=\"214\" y2=\"78\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"214,78 215.7,72.3 219.3,75.3\" fill=\"#c9a04a\"/><line x1=\"256\" y1=\"42\" x2=\"286\" y2=\"78\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"286,78 280.7,75.3 284.3,72.3\" fill=\"#c9a04a\"/><text x=\"210\" y=\"92\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">A</text><text x=\"290\" y=\"92\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">B</text><text x=\"250\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">第3の何かCが両方を動かした</text><text x=\"170\" y=\"132\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\">見えている相関だけでは、この3つを区別できない</text></svg>", "terms": [["相関", "2つのことが一緒に増えたり減ったりする関係。原因と結果の向きまでは含まない"], ["因果", "片方が原因で、もう片方が結果として起きるという関係"], ["交絡", "見えている2つのことの裏で、両方を動かしている第3の何かのこと"]], "think": "「AとBが一緒に動いている」という1つの事実だけからは、Aが原因でBが起きたのか、逆にBが原因でAが起きたのか、それとも第3の何かCが両方を動かしているだけなのか、区別がつかない。猫と貯金の例でも、「几帳面な性格の人ほど猫の世話も貯金も両方きちんとやる」というように、性格という第3の要因が裏にある可能性が残る。だから相関が1つ見つかった段階では、まだ因果とは呼べない。", "vs": "「一緒に動いている（相関）」と「原因になっている（因果）」を同じ意味で使ってしまうのが一番多い勘違い。相関は因果の証拠の1つにはなるが、それだけでは因果の証明にはならない。", "why_asked": "ニュースや広告には「〇〇な人ほど△△」という相関の話を、そのまま因果のように語る例があふれている。相関と因果を分けて考えられないと、効果のない対策にお金や時間を使ってしまう。", "usecase": "「朝食を食べる子どもほど成績がよい」というデータを見て、すぐに「朝食を食べさせれば成績が上がる」と結論しない。生活習慣の整った家庭という共通の背景を疑う、といった考え方に使う。", "opt": ["正解。データが示しているのは「一緒に動いている」という相関だけで、猫が貯金を増やす原因だという証拠にはなっていない。", "この文は相関を因果だと決めつけている。猫を飼う家庭に共通する別の理由（性格や生活習慣など）が裏にある可能性がまだ残っている。", "こちらも因果の向きを決めつけている。データからは「どちらが先か」までは分からない。", "貯金が多い家庭ほど猫を飼う割合が高いというデータがある以上、「まったく関係がない」とは言えない。関係はあるが、原因とまでは言えないだけ。"]}'),

  ('stats6-q02', '因果推論',
   '気温が高い日ほど、アイスクリームの売上も水難事故の件数も増えるというデータがある。「気温」に注目すると、この関係がすっきり説明できる。この現象を何と呼ぶ？',
   NULL::text,
   '["交絡（気温という共通の原因が、アイスの売上と水難事故の両方を押し上げている）", "逆の因果（水難事故が増えると、アイスがよく売れるようになるという向きの関係）", "セレクションバイアス（事故のデータを集める過程そのものに偏りが生じている状態）", "まったくの偶然の一致で、共通の原因は存在しない状態"]',
   0, '[0]', 'single',
   '{"asked": "相関の裏に隠れている「共通の原因」の名前と見つけ方。", "point": "見えている2つのことの裏に、両方を動かしている第3の要因がいないかを疑う。それが交絡。", "kid": "交絡は、AとBが一緒に動いて見える裏で、実は「Cという別の何か」がAもBも両方動かしている状態のこと。CのせいでAとBが関係あるように見えているだけで、AとBの間に直接の関係は無い。", "eg": "花火大会の日は、屋台の売上も、駐輪場の混雑も両方増える。屋台と駐輪場に直接の関係はなく、「花火大会」という共通の原因が両方を動かしているだけ。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">気温という共通の原因が、両方を押し上げている</text><text x=\"170\" y=\"42\" fill=\"#c9a04a\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">気温</text><line x1=\"158\" y1=\"50\" x2=\"92\" y2=\"92\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"92,92 95.4,87.1 97.9,91.0\" fill=\"#c9a04a\"/><line x1=\"182\" y1=\"50\" x2=\"248\" y2=\"92\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"248,92 242.1,91.0 244.6,87.1\" fill=\"#c9a04a\"/><text x=\"80\" y=\"108\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">アイスの売上</text><text x=\"260\" y=\"108\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">水難事故</text><line x1=\"105\" y1=\"100\" x2=\"235\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><text x=\"170\" y=\"116\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">直接の原因ではない</text><text x=\"170\" y=\"136\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">この「共通の原因」を交絡（交絡因子）と呼ぶ</text></svg>", "terms": [["交絡", "見えている2つのことの裏で、両方を動かしている第3の要因"], ["交絡因子", "交絡を引き起こしている、その「第3の要因」そのもの"]], "think": "アイスの売上と水難事故は、どちらも「気温が高い」という共通の原因から生まれた結果どうし。気温が上がると、暑いのでアイスを買う人が増え、同時に、暑いので川や海で泳ぐ人も増えて事故も増える。アイスと水難事故を直接つないでいる矢印は無く、気温という共通の土台から2本の矢印が伸びているだけ。この土台（気温）を見つけずに「アイスと水難事故に関係がある」とだけ言うと、話がおかしくなる。", "vs": "逆の因果は「BがAを引き起こす」という向きだけが逆の話で、第3の要因は出てこない。交絡は登場人物が1人増えて、AともBとも関係のある「隠れた原因」が別にいる状態を指す。", "why_asked": "交絡に気づかずデータを読むと、まったく効果のない物を「効果がある」と誤解してしまう。因果推論という分野は、この交絡をどう見つけて取り除くかが最大のテーマの1つ。", "usecase": "健康調査で「コーヒーをよく飲む人ほど病気が多い」というデータが出ても、「喫煙者にコーヒー好きが多い」という交絡（タバコが真の原因）を疑う、といった読み方に使う。", "opt": ["正解。気温という共通の原因が、アイスの売上と水難事故の両方を押し上げている。これが交絡。", "アイスの売上が水難事故の原因になっている、あるいはその逆だという話ではない。両方とも気温という別の要因から生まれた結果。", "データの集め方に偏りがある状態の名前で、今回のように「共通の原因が両方に効いている」話とは別物。", "気温という共通の原因がはっきりある以上、「共通の原因が存在しない偶然の一致」とは言えない。"]}'),

  ('stats6-q03', '因果推論',
   '新しい肥料の効果を調べるのに、研究者が畑を2つに分け、片方だけ肥料を撒いて収穫量を比べた。この「研究者が自分で条件を割り振って比べる」方法を何と呼ぶ？',
   NULL::text,
   '["実験研究（研究者が意図的に条件を割り振って比べる方法）", "観察研究（すでにある条件の違いを、そのまま比べる方法）", "縦断研究（同じ対象を長期間にわたって追いかけて記録する方法）", "横断研究（ある一時点のデータをまとめて集めて比べる方法）"]',
   0, '[0]', 'single',
   '{"asked": "研究者が条件を割り振れる調べ方と、割り振れずに眺めるだけの調べ方の違い。", "point": "「誰にどの条件を与えるか」を研究者が決められるなら実験研究、決められずすでにある違いを見るだけなら観察研究。", "kid": "実験研究は、研究者が「こっちには肥料を撒く、こっちには撒かない」と自分で条件を割り振ってから比べる方法。観察研究は、もともと肥料を使っている農家と使っていない農家のように、すでにある違いをそのまま集めて比べる方法。", "eg": "料理の味くらべで言うと、実験研究は「同じ材料から自分で塩の量だけ変えた2皿」を比べること。観察研究は「街の色々なお店の、もともとの味つけ」を集めて比べること。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"88\" y=\"20\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">実験研究</text><circle cx=\"60\" cy=\"46\" r=\"12\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"60\" y=\"50\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">研</text><line x1=\"72\" y1=\"46\" x2=\"100\" y2=\"46\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"100,46 94.5,48.3 94.5,43.7\" fill=\"#3b82f6\"/><text x=\"120\" y=\"50\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">肥料あり</text><circle cx=\"60\" cy=\"78\" r=\"12\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"60\" y=\"82\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">研</text><line x1=\"72\" y1=\"78\" x2=\"100\" y2=\"78\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"100,78 94.5,80.3 94.5,75.7\" fill=\"#3b82f6\"/><text x=\"120\" y=\"82\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">肥料なし</text><text x=\"88\" y=\"100\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">研究者が自分で割り振る</text><line x1=\"170\" y1=\"14\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\"/><text x=\"255\" y=\"20\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">観察研究</text><text x=\"255\" y=\"50\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">もともと肥料を使う農家</text><text x=\"255\" y=\"78\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">もともと使わない農家</text><text x=\"255\" y=\"100\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">すでにある違いをそのまま見る</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">介入して分けるか／見ているだけか</text></svg>", "terms": [["実験研究", "研究者が条件を割り振って、その結果を比べる調べ方"], ["観察研究", "研究者は割り振らず、すでにある違いをそのまま観察して比べる調べ方"]], "think": "実験研究では、研究者が「どちらの畑に肥料を撒くか」を決めるので、肥料の有無以外の条件（土の質や日当たりなど）をできるだけそろえて比べられる。観察研究では、もともと肥料を使っている農家と使っていない農家は、土地の広さや資金力なども最初から違っているかもしれない。研究者が割り振れるかどうかが、あとで交絡を疑う必要があるかどうかの分かれ目になる。", "vs": "縦断研究・横断研究は「時間の使い方」に注目した分類（追いかけるか、一時点で見るか）で、実験研究・観察研究とは分類の軸そのものが違う。実験研究にも観察研究にも、縦断的なものと横断的なものがありうる。", "why_asked": "「研究者が割り振れるかどうか」は、そのあとの分析で交絡を心配する必要があるかどうかを大きく左右する。この区別を土台にして、この先RCTや傾向スコアを習っていく。", "usecase": "新薬の効き目を確かめる治験は実験研究、すでに薬を使っている患者と使っていない患者のカルテを比べる調査は観察研究。どちらの立場でデータが作られたかを知ってから読む。", "opt": ["正解。研究者が自分で「肥料あり・なし」を割り振ってから比べているので実験研究。", "観察研究は、もともとある違いをそのまま比べる方法。今回は研究者が自分で条件を割り振っているので当てはまらない。", "縦断研究は同じ対象を長期間追いかける調べ方のことで、条件を割り振るかどうかの話とは軸が異なる。", "横断研究はある一時点でまとめてデータを集める調べ方のことで、条件を割り振るかどうかの話とは軸が異なる。"]}'),

  ('stats6-q04', '因果推論',
   '新しい薬の効果を調べる実験で、薬を飲むグループのほかに、比較のためにあえて薬を飲まないグループも用意した。この「比べる相手として薬を飲まないグループ」を何と呼ぶ？',
   NULL::text,
   '["対照群（比較のために処理を与えないグループ）", "処理群（調べたい処理・介入を与えるグループ）", "母集団（今回の調査で対象にしたい人たち全体）", "サンプル（母集団の中から実際に調査のために取り出した一部）"]',
   0, '[0]', 'single',
   '{"asked": "「比べる相手」として用意するグループの名前。", "point": "調べたい処理を与えるのが処理群、比較のためにあえて何も与えないのが対照群。", "kid": "薬の効果を知りたいなら、薬を飲む人だけを見ていても「薬のおかげ」なのか「放っておいても治った」のか分からない。そこで、薬を飲まない人たちのグループも用意して両方を比べる。薬を飲む方が処理群、飲まない方が対照群。", "eg": "植物の水やり実験で、水をたっぷりあげる鉢が処理群なら、水をあげない鉢が対照群。対照群があるから「水のおかげで育った」と言える。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"30\" y=\"34\" width=\"130\" height=\"46\" rx=\"8\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"95\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">処理群</text><text x=\"95\" y=\"70\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">新しい薬を飲む</text><rect x=\"180\" y=\"34\" width=\"130\" height=\"46\" rx=\"8\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"245\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">対照群</text><text x=\"245\" y=\"70\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">薬を飲まない</text><line x1=\"160\" y1=\"57\" x2=\"180\" y2=\"57\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"46\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">比べる</text><text x=\"170\" y=\"104\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">対照群という「比べる相手」がいないと</text><text x=\"170\" y=\"120\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">薬が効いたのかどうか判断できない</text></svg>", "terms": [["処理群", "調べたい処理（薬・肥料・新しい教材など）を与えるグループ"], ["対照群", "比較のために、あえてその処理を与えないグループ"]], "think": "対照群がいないと、薬を飲んだグループの体調がよくなっても、それが薬のおかげなのか、時間がたてば自然に治ったのか、区別ができない。対照群という「薬を飲まなかった場合どうなっていたか」を映す鏡を用意することで、はじめて「処理群と対照群の差＝薬の効果」と言えるようになる。", "vs": "処理群と対照群は「役割の名前」で、母集団やサンプルは「集団の大きさ・範囲の名前」。母集団は調べたい対象の全体、サンプルはそこから実際に取り出した一部を指し、比べるための2つのグループという話ではない。", "why_asked": "「比べる相手を用意する」という発想そのものが、これから習うRCTや差の差法などすべての土台になる。対照群の無い実験は、効果があったかどうかを語れない。", "usecase": "新薬の治験（本物の薬と偽薬を比べる）、新しい教材の効果測定（新教材を使う組と使わない組を比べる）。「効果があった」と主張したいときは、必ず対照群と比べているかを確認する。", "opt": ["正解。比較のために、あえて薬という処理を与えないグループが対照群。", "処理群は逆に、調べたい薬を実際に飲むグループのことで、比較のための「飲まない側」ではない。", "母集団は今回の調査で対象にしたい人たち全体のことで、実験の中の2つのグループの一方を指す言葉ではない。", "サンプルは母集団から取り出した調査対象全体を指す言葉で、実験の中の「比べる相手」の名前ではない。"]}'),

  ('stats6-q05', '因果推論',
   '新しい教材の効果を調べたい。生徒をくじ引きで無作為に2グループに分け、片方だけ新しい教材を使わせて、あとでテストの点を比べた。この「くじ引きで無作為に2グループへ振り分ける」研究方法を何と呼ぶ？',
   NULL::text,
   '["RCT（無作為化比較試験。くじ引きで2グループに分けて比較する研究）", "傾向スコアマッチング（似た特徴を持つ対象どうしを、あとから組にする方法）", "観察研究（すでにある集団の違いを、そのまま比較する方法）", "コホート研究（同じ集団を時間をかけて追いかける方法）"]',
   0, '[0]', 'single',
   '{"asked": "くじ引きで無作為に分ける研究方法の名前と、それが交絡を消せる理由。", "point": "くじ引きで無作為に振り分けると、隠れた交絡も含めて、あらゆる違いが両グループに均等に散らばる。", "kid": "RCTは、誰が新しい教材を使うグループになるかを、じゃんけんやくじ引きのように偶然だけで決める研究方法。研究者の好みや生徒の希望が入り込まないので、2つのグループはもともとほぼ同じ集まりになる。", "eg": "トランプを混ぜてから山を2つに分けると、強いカードも弱いカードもだいたい半分ずつ散らばる。狙って強いカードだけ片方に集めることはできない。くじ引きによる振り分けも同じ発想。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"130\" y=\"14\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"170\" y=\"33\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">くじ引き</text><line x1=\"150\" y1=\"44\" x2=\"90\" y2=\"78\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"90,78 93.7,73.2 96.0,77.3\" fill=\"#60a5fa\"/><line x1=\"190\" y1=\"44\" x2=\"250\" y2=\"78\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"250,78 244.0,77.3 246.3,73.2\" fill=\"#60a5fa\"/><rect x=\"30\" y=\"80\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"90\" y=\"99\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">教材あり群</text><rect x=\"190\" y=\"80\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"250\" y=\"99\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">教材なし群</text><text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">無作為だから、学力や家庭環境の偏りも両群に均等に散る</text></svg>", "terms": [["RCT", "対象をくじ引きのように無作為に2グループへ振り分けて比較する研究方法。ランダム化比較試験ともいう"], ["無作為化", "人の意思を挟まず、偶然だけでグループを決めること"]], "think": "なぜくじ引きだと交絡が消えるのかがカギ。学力の高い生徒も低い生徒も、家庭が裕福な生徒もそうでない生徒も、くじ引きの結果とは無関係にどちらのグループに入るかが決まる。人数が十分多ければ、学力や家庭環境といった無数の隠れた要因は、確率の法則でだいたい半分ずつ両グループに散らばる。その結果、2グループの違いは「教材を使ったかどうか」だけになり、テストの点の差をそのまま教材の効果として読める。", "vs": "傾向スコアは、くじ引きができない観察データに対して「あとから」似た者どうしをそろえる工夫。RCTは「あらかじめ」くじ引きで条件をそろえてしまう点が違う。RCTのほうが交絡を消す力は強いが、実施できない場面も多い。", "why_asked": "交絡を確実に消せる、因果推論でもっとも強力な方法だから。新薬の承認審査など、効果を厳密に証明したい場面では基本的にRCTが求められる。", "usecase": "新薬の治験、新しい教育方法の効果測定、Webサービスの画面デザインをどちらにすべきか決めるA/Bテストは、すべてRCTの考え方そのもの。", "opt": ["正解。くじ引きで無作為に2グループへ振り分けて比較する研究方法がRCT。", "傾向スコアは、くじ引きができない場合に、あとから似た条件の対象どうしをそろえる方法。あらかじめくじ引きで分ける今回の方法とは順番が逆。", "観察研究は、もともとある違いをそのまま比べる方法。今回はくじ引きで研究者が積極的に条件を割り振っているので当てはまらない。", "コホート研究は、ある集団を長い時間をかけて追いかける調べ方のことで、くじ引きで分けるかどうかとは別の軸の話。"]}'),

  ('stats6-q06', '因果推論',
   '第二次大戦中、生きて帰ってきた爆撃機の弾痕を調べたところ、主翼や胴体には多く、コックピットやエンジン付近には少なかった。ある研究者は「弾痕が少ない部分こそ補強すべきだ」と主張した。この主張の根拠になった、データの偏りを何と呼ぶ？',
   NULL::text,
   '["セレクションバイアス（撃たれても生きて帰れた機体だけを見ているという、選ばれ方の偏り）", "交絡（弾痕の場所と生還率の両方に影響している、隠れた第3の要因があるという状態）", "疑似相関（交絡とは別に、直接の関係がない2つの出来事がたまたま同時に起きて見えるだけの関係）", "実験研究（研究者が条件を意図的に割り振ってから比較する調べ方のこと）"]',
   0, '[0]', 'single',
   '{"asked": "「見えているデータ」そのものが、すでに偏った集め方をされている状態の名前。", "point": "帰ってきた機体だけを見ている時点で、そこを撃たれた機体はもう帰ってきていない、という可能性を忘れてはいけない。", "kid": "セレクションバイアスは、調べる対象の「選ばれ方」自体に偏りがあるせいで、データが本当の姿を映していない状態のこと。今回は「生きて帰ってきた機体」しか調べられていない。撃たれても平気だった部分に弾痕が多く残るのは、そこを撃たれても帰ってこられたから。逆にコックピットやエンジンに弾痕が少ないのは、そこを撃たれた機体は帰ってこられず、そもそも調査の対象にすら入っていないから。", "eg": "退院した患者だけにアンケートを取って「この病院の治療は効果がある」と言うようなもの。亡くなった患者は最初からアンケートに答えられず、良い結果だけが目立って見えてしまう。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M60 60 L280 60 L300 66 L280 72 L60 72 Z\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M150 44 L190 44 L172 60 Z\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M120 72 L100 96 M160 72 L160 96\" stroke=\"#8892a4\" stroke-width=\"1.2\"/><circle cx=\"90\" cy=\"64\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"105\" cy=\"68\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"65\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"200\" cy=\"66\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"215\" cy=\"63\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"230\" cy=\"68\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"245\" cy=\"65\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"95\" cy=\"52\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"260\" cy=\"64\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"210\" cy=\"70\" r=\"2.6\" fill=\"#60a5fa\"/><circle cx=\"172\" cy=\"52\" r=\"7\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/><text x=\"172\" y=\"24\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">コックピット</text><circle cx=\"128\" cy=\"86\" r=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/><text x=\"128\" y=\"108\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">エンジン</text><text x=\"170\" y=\"124\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">弾痕は「無事に帰ってきた機体」だけのデータ</text><text x=\"170\" y=\"140\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">撃たれた所が少ないのではなく、そこを撃たれた機体は帰れなかった</text></svg>", "terms": [["セレクションバイアス", "対象の選ばれ方に偏りがあるせいで、データ全体が実態とずれてしまう状態"], ["生存バイアス", "「生き残った・成功した」対象しか見えていないことで起きる、セレクションバイアスの代表例"]], "think": "「弾痕が少ない部分は安全だ」という考えは、目の前のデータをそのまま信じている。しかし今調べているのは「生きて帰ってきた機体」だけであり、撃墜されて帰ってこなかった機体のデータはそもそも手元に存在しない。もしコックピットやエンジンを撃たれた機体の多くが撃墜されていたのなら、弾痕が少ないのはそこが安全だからではなく、そこを撃たれると生き残れないから、というまったく逆の意味になる。だから本当に補強すべきなのは、生還機に弾痕が少ない部分だという結論になる。", "vs": "交絡は「見えているデータの中で、別の要因が両方を動かしている」状態。セレクションバイアスは「そもそもデータに入ってくる対象の選ばれ方自体」が偏っている状態で、問題が起きている段階が異なる。", "why_asked": "生き残った例・成功した例だけを見て法則を語ってしまう失敗は、統計だけでなくビジネスや進路選びの話でも頻繁に起きる。見えていないデータの存在に気づけるかどうかを問うための定番の例。", "usecase": "「成功した起業家の共通点」を成功者だけにアンケートして調べる調査は、失敗して姿を消した人たちを見落としているセレクションバイアスの典型。データの集め方をまず疑う習慣に使う。", "opt": ["正解。生きて帰れた機体だけを見ているという、対象の選ばれ方そのものの偏りがセレクションバイアス。", "今回の話は、両方に効く第3の要因が別にいるという話ではなく、そもそも見えているデータの集め方が偏っているという話。", "疑似相関は、交絡とは別に、直接の関係がない2つのことが偶然一緒に動いて見えるだけの話で、今回のように「一部のデータしか手元にない」状態とは別物。", "研究者が条件を割り振って比べているわけではなく、すでに起きた戦闘の結果を後から観察しているだけなので、実験研究には当てはまらない。"]}'),

  ('stats6-q07', '因果推論',
   'くじ引きで2グループに分けることができない観察データで、「タバコを吸う人」と「吸わない人」を、年齢・性別・運動習慣などの条件が似た者どうしであとからペアにして比較したい。この手法を何と呼ぶ？',
   NULL::text,
   '["傾向スコア（複数の条件から「似た者どうし」をあとからそろえてペアにする方法）", "RCT（くじ引きで対象をあらかじめ、ほぼ同じ条件になるよう2グループに振り分ける方法）", "差の差法（前後の変化の差を、2つのグループのあいだでさらに引き算する方法）", "セレクションバイアス（比べている集団の選ばれ方そのものに偏りがある状態）"]',
   0, '[0]', 'single',
   '{"asked": "くじ引きができない観察データで、あとから条件をそろえるための工夫。", "point": "年齢や生活習慣など複数の条件を1つの点数にまとめ、似た点数どうしをペアにするのが傾向スコア。", "kid": "傾向スコアは、「年齢・性別・運動習慣など、条件がいろいろ違う人たち」を、1つの点数（スコア）に要約してから、似た点数の人どうしをペアにして比べる方法。くじ引きができない観察データでも、あとからできるだけ公平に近い比較を作るための工夫。", "eg": "体重別に組み分けする格闘技の試合のように、身長・体重・年齢などバラバラな条件を1つの「階級」にまとめてから、似た階級どうしを戦わせるイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"18\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">年齢・性別・運動習慣…</text><text x=\"90\" y=\"32\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">複数の条件</text><line x1=\"90\" y1=\"40\" x2=\"90\" y2=\"62\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"90,62 87.7,56.5 92.3,56.5\" fill=\"#60a5fa\"/><rect x=\"55\" y=\"66\" width=\"70\" height=\"24\" rx=\"12\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"90\" y=\"82\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">1つの点数</text><line x1=\"125\" y1=\"78\" x2=\"165\" y2=\"78\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"165,78 159.5,80.3 159.5,75.7\" fill=\"#60a5fa\"/><text x=\"220\" y=\"60\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">似た点数どうし</text><circle cx=\"200\" cy=\"82\" r=\"4.5\" fill=\"#3b82f6\"/><text x=\"200\" y=\"96\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">喫煙あり</text><circle cx=\"240\" cy=\"82\" r=\"4.5\" fill=\"#8892a4\"/><text x=\"240\" y=\"96\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">喫煙なし</text><line x1=\"205\" y1=\"82\" x2=\"235\" y2=\"82\" stroke=\"#2a2f3f\" stroke-dasharray=\"2 2\"/><text x=\"220\" y=\"108\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">を後からペアにする</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">くじ引きができない観察データで、条件をそろえ直す工夫</text></svg>", "terms": [["傾向スコア", "複数の条件から計算した、1人1人の「その処理を受けやすさ」を表す1つの点数"], ["マッチング", "傾向スコアなどが似ている対象どうしを、あとからペアにする作業"]], "think": "喫煙者と非喫煙者をそのまま比べると、年齢や運動習慣といった多くの条件が最初からバラバラで、病気の差が本当にタバコのせいなのか、それとも他の条件の違いのせいなのか分からなくなる。すべての条件を1つずつそろえてペアを探すのは大変なので、それらの条件から「タバコを吸いそうな人かどうか」を表す1つの点数（傾向スコア）を計算し、その点数が近い人どうしをペアにする。これにより、くじ引きに近い、公平な比較をあとから作り出せる。", "vs": "RCTは実験の前にくじ引きで条件をそろえる方法、傾向スコアはすでに集まった観察データに対して実験のあとから条件をそろえ直す方法。順番と、くじ引きを使えるかどうかが違う。", "why_asked": "くじ引きができない場面（すでに喫煙している人を無理やり禁煙させるような実験はできない）は世の中に多い。観察データしか無い状況でも交絡をできるだけ抑えるための現実的な手段として発展した。", "usecase": "医療統計で、すでに服薬している患者としていない患者の効果を比較するとき。教育政策で、すでに私立に通う生徒と公立に通う生徒の学力を比較するときなど、実験ができない社会科学の分析でよく使われる。", "opt": ["正解。複数の条件を1つの点数にまとめ、似た点数どうしをペアにして比べるのが傾向スコア。", "RCTは実験を始める前にくじ引きで条件をそろえる方法で、すでにある観察データをあとから調整する今回の話とは順序が逆。", "差の差法は、政策の前後の変化どうしを引き算する方法で、条件が似た者どうしをペアにする話とは着眼点が異なる。", "セレクションバイアスは、データの集め方自体が偏っている状態を指す言葉で、条件をそろえて比較する工夫そのものを指す言葉ではない。"]}'),

  ('stats6-q08', '因果推論',
   '最低賃金を引き上げた州と、引き上げなかった州で、それぞれ「引き上げ前後の雇用者数の変化」を求め、その変化どうしをさらに引き算して政策の効果を測る手法を何と呼ぶ？',
   NULL::text,
   '["差の差法（政策があった州の変化から、なかった州の変化を引いて、政策の効果を取り出す方法）", "RCT（くじ引きで対象を無作為に2グループへあらかじめ振り分けてから、前後の変化を比較する方法）", "傾向スコア（似た条件を持つ対象どうしを、あとからそろえてペアにする方法）", "交絡（比較している2つの州の違いに、共通の別の原因が隠れている状態）"]',
   0, '[0]', 'single',
   '{"asked": "「前後の変化」を、2つのグループのあいだでさらに比べる手法の名前。", "point": "政策があった州の変化から、なかった州の変化を引き算すると、時代の流れの影響が消えて政策そのものの効果が残る。", "kid": "差の差法は、政策があった州の「前後の変化」と、政策がなかった州の「前後の変化」を両方求めて、その2つの変化どうしを引き算する方法。景気全体の動きのような、両方の州に共通する変化を引き算で消してしまう工夫。", "eg": "2つのクラスの身長の伸びを比べるとき、片方には特別な体操をさせた。ただの身長差ではなく、「体操させたクラスの伸び」から「させなかったクラスの伸び」を引き算すれば、成長期そのものの伸びは消えて、体操の効果だけが残る。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"24\" y1=\"112\" x2=\"252\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"24\" x2=\"150\" y2=\"112\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"150\" y=\"18\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">政策の実施</text><line x1=\"34\" y1=\"70\" x2=\"150\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><line x1=\"150\" y1=\"60\" x2=\"248\" y2=\"44\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><text x=\"255\" y=\"40\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"start\">実施した州</text><line x1=\"34\" y1=\"90\" x2=\"150\" y2=\"85\" stroke=\"#8892a4\" stroke-width=\"1.6\"/><line x1=\"150\" y1=\"85\" x2=\"248\" y2=\"76\" stroke=\"#8892a4\" stroke-width=\"1.6\"/><text x=\"255\" y=\"80\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"start\">実施しない州</text><line x1=\"250\" y1=\"44\" x2=\"250\" y2=\"76\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"230\" y=\"60\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"end\" font-weight=\"600\">差の差</text><text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">2つの州の「変化」どうしを、さらに引き算して政策の効果を取り出す</text></svg>", "terms": [["差の差法", "2つのグループの「前後の変化」どうしを、さらに引き算して効果を取り出す方法"], ["トレンド", "政策の有無にかかわらず、時代の流れで自然に起きている変化のこと"]], "think": "政策があった州の雇用者数がただ増えただけでは、それが政策のおかげなのか、そもそも景気がよくて全国的に雇用が増えていた時期だったのかが分からない。そこで、政策がなかった州の「前後の変化」も同時に求める。政策がなかった州の変化は、景気全体のようなトレンドの影響だけを表していると考えられる。政策があった州の変化から、この「トレンドだけの変化」を引き算すれば、残るのは政策そのものの効果だけになる。", "vs": "RCTはくじ引きで実験の前からグループをそろえる方法、差の差法はくじ引きができない状況で、前後の変化を引き算することで政策の効果だけを浮かび上がらせる方法。どちらも交絡を抑える工夫だが、使う場面と仕組みが異なる。", "why_asked": "最低賃金や税制のような政策は、全員にくじ引きで実施したり止めたりできない。すでに一部の地域だけで実施された政策の効果を、あとから公平に測るための代表的な手法として経済学や政策評価で広く使われている。", "usecase": "ある県だけで実施した子育て支援政策の効果測定、一部店舗だけで導入した新しい接客方法の効果測定など、「一部にだけ先に実施された変化」の効果をあとから測るときに使う。", "opt": ["正解。政策のあった州の変化から、なかった州の変化を引き算して、政策そのものの効果を取り出す方法。", "RCTは実験の前にくじ引きで対象を振り分ける方法で、すでに一部の州にだけ実施された政策をあとから評価する今回の状況には使えない。", "傾向スコアは条件が似た対象どうしをペアにする方法で、前後の変化どうしを引き算するという今回の着眼点とは異なる。", "交絡は共通の隠れた原因がある状態を指す言葉で、それを消すための引き算の手法そのものを指す言葉ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
